import * as T from './vendor/three.module.js';
const vectors=['home','target','patrolTarget','aggro','aggroOrigin'];
const numbers=['hp','maxHp','heading','generation','cooldown','timer','stun','slow','root','attackWindup','bleedLeft','bleedNext','bleedDamage','markLeft'];
export function packActor(n){const state={id:n.id??null,position:n.g.position.toArray(),visible:n.g.visible,hit:!!n.hit};for(const key of numbers)if(Number.isFinite(n[key]))state[key]=n[key];for(const key of vectors)state[key]=n[key]?.toArray?.()??null;if(n.mode)state.mode=n.mode;return state}
export function restoreActor(n,state){n.g.position.fromArray(state.position);n.g.visible=state.visible;n.hit=state.hit;delete n.root;delete n.stun;delete n.slow;delete n.attackWindup;for(const k of ['bleedLeft','bleedNext','bleedDamage','markLeft'])delete n[k];for(const key of numbers)if(state[key]!==undefined)n[key]=state[key];for(const key of vectors)n[key]=state[key]?new T.Vector3().fromArray(state[key]):null;if(n.attackWindup>0)n.cueAttack?.('bite',n.attackWindup+.25);if(state.mode)n.mode=state.mode;n.g.rotation.y=n.heading||0}
